/**
 * End-to-end coverage for forcing a named LMDB execution strategy, from
 * {@code SailQuery.setForcedLmdbExecutionStrategy(String)} through {@code SlowQueryContextHolder},
 * {@link LmdbNativeEvaluationStrategy}, and {@link LmdbNativeStrategyArbiter}. Every test drives a real query against a
 * real {@link LmdbStore} rather than an internal test seam, so a break anywhere along that chain shows up here.
 */
class LmdbNativeForcedExecutionStrategyTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI alice = vf.createIRI(EX, "alice");
			IRI bob = vf.createIRI(EX, "bob");
			IRI knows = vf.createIRI(EX, "knows");
			IRI worksAt = vf.createIRI(EX, "worksAt");
			IRI acme = vf.createIRI(EX, "acme");
			conn.begin();
			conn.add(alice, knows, bob);
			conn.add(alice, worksAt, acme);
			conn.add(bob, worksAt, acme);
			conn.commit();
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private static final String SINGLE_PATTERN_QUERY = "PREFIX ex: <" + EX + "> "
			+ "SELECT ?p1 ?p2 WHERE { ?p1 ex:knows ?p2 }";

	private static final String MULTI_PATTERN_JOIN_QUERY = "PREFIX ex: <" + EX + "> "
			+ "SELECT ?p1 WHERE { ?p1 ex:knows ?p2 . ?p1 ex:worksAt ?c . ?p2 ex:worksAt ?c }";

	private static final String MULTI_PATTERN_ORDERED_QUERY = MULTI_PATTERN_JOIN_QUERY + " ORDER BY ?p1";

	private SailTupleQuery prepare(SailRepositoryConnection conn, String query, String forcedStrategy) {
		SailTupleQuery preparedQuery = (SailTupleQuery) conn.prepareTupleQuery(QueryLanguage.SPARQL, query);
		preparedQuery.setForcedLmdbExecutionStrategy(forcedStrategy);
		return preparedQuery;
	}

	@Test
	void noForcingRequestedBehavesNormally() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY, null);
			assertThat(QueryResults.asList(preparedQuery.evaluate())).hasSize(1);
		}
	}

	@Test
	void notActivatedSentinelMeansNoForcing() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY,
					LmdbNativeForceableStrategies.NOT_ACTIVATED);
			assertThat(QueryResults.asList(preparedQuery.evaluate())).hasSize(1);
		}
	}

	/**
	 * The empty string is the "no strategy" entry of the Workbench's dropdown and of any other form-shaped caller: a
	 * blank selection must mean "let the store choose", exactly like {@code null}. Previously it reached the name
	 * validation and failed the query with {@code Unknown LMDB execution strategy ''}, which made an empty option
	 * impossible to offer in a UI.
	 */
	@Test
	void emptyStrategyMeansNoForcing() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY, "");
			assertThat(QueryResults.asList(preparedQuery.evaluate())).hasSize(1);
		}
	}

	/** As {@link #emptyStrategyMeansNoForcing()}, for a selection that carries only whitespace. */
	@Test
	void blankStrategyMeansNoForcing() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY, "   ");
			assertThat(QueryResults.asList(preparedQuery.evaluate())).hasSize(1);
		}
	}

	@Test
	void forcingNestedLoopAlwaysSucceedsBecauseItIsTheUniversalFallback() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY,
					LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			List<BindingSet> result = QueryResults.asList(preparedQuery.evaluate());
			assertThat(result).hasSize(1);
		}
	}

	/**
	 * Pins the mandatory/soft distinction on {@code LmdbNativeStrategyArbiter}: the {@code ORDER BY} fusion site (which
	 * forces "where applicable") must quietly decline when the forced tag is not part of its own candidate family and
	 * let the caller's own fallback to {@code openUnorderedInput} (the mandatory row/join dispatch site) try the forced
	 * tag there instead. Before that distinction existed, forcing {@code nestedLoop} on a query with an
	 * {@code ORDER BY} would fail at the {@code ORDER BY} site for no reason, even though {@code nestedLoop} is always
	 * legal at row/join dispatch.
	 */
	@Test
	void forcingATagOnlyLegalAtRowDispatchStillSucceedsWhenTheQueryAlsoHasAnOrderBy() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, MULTI_PATTERN_ORDERED_QUERY,
					LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			List<BindingSet> result = QueryResults.asList(preparedQuery.evaluate());
			assertThat(result).hasSize(1);
		}
	}

	@Test
	void unknownStrategyNameFailsImmediatelyWithTheValidNameList() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY, "totally-bogus-strategy-name");
			assertThatThrownBy(preparedQuery::evaluate)
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("Unknown LMDB execution strategy 'totally-bogus-strategy-name'")
					.hasMessageContaining(LmdbNativeForceableStrategies.NOT_ACTIVATED)
					.hasMessageContaining(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
		}
	}

	/**
	 * {@code irKernelDistinct} is only ever offered when the query has {@code DISTINCT} and no {@code ORDER BY}, so on
	 * a plain (non-distinct) single-pattern query its own {@code arbiter.offer(...)} call at row/join dispatch is never
	 * even reached — the detailed error must say the strategy was never a candidate, not fabricate a decline reason.
	 * The failure surfaces only once the returned result is actually iterated ({@code QueryResults.asList}), not from
	 * {@code evaluate()} itself: row production, and therefore arbitration, is lazy.
	 */
	@Test
	void forcingAStrategyNeverOfferedForThisQueryShapeFailsWithoutAFabricatedReason() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY,
					LmdbNativeAttemptMetrics.PATH_IR_KERNEL_DISTINCT);
			assertThatThrownBy(() -> QueryResults.asList(preparedQuery.evaluate()))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("'" + LmdbNativeAttemptMetrics.PATH_IR_KERNEL_DISTINCT + "'")
					.hasMessageContaining("row/join dispatch")
					.hasMessageContaining("never a candidate");
		}
	}

	/**
	 * {@code factorizedRows} is offered unconditionally at row/join dispatch but declines internally with the verbatim
	 * reason {@code "not-multi-join"} whenever the compiled plan is not a multi-pattern join — exactly the shape of
	 * {@link #SINGLE_PATTERN_QUERY}. The detailed error must quote that real, already-captured reason rather than a
	 * generic message. As above, the failure only surfaces once the result is iterated.
	 */
	@Test
	void forcingAStrategyThatIsOfferedButDeclinesQuotesTheRealReason() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, SINGLE_PATTERN_QUERY,
					LmdbNativeAttemptMetrics.PATH_FACTORIZED_ROWS);
			assertThatThrownBy(() -> QueryResults.asList(preparedQuery.evaluate()))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("'" + LmdbNativeAttemptMetrics.PATH_FACTORIZED_ROWS + "'")
					.hasMessageContaining("declined")
					.hasMessageContaining("not-multi-join");
		}
	}

	private static final String GROUP_BY_QUERY = "PREFIX ex: <" + EX + "> "
			+ "SELECT ?p (count(*) as ?count) WHERE { ?s ex:worksAt ex:acme . ?s ?p ?o } GROUP BY ?p";

	/**
	 * Regression guard for a forced strategy silently doing nothing on a {@code GROUP BY} query.
	 * {@code NativeGroupStep} builds its arbiter lazily, on the first {@code hasNext()} — long after
	 * {@code sailCon.evaluate(...)} returned and {@code SlowQueryContextHolder} was restored — so reading the request
	 * from the thread-local at that point always yielded {@code null}: the strategy was neither honored nor reported as
	 * impossible. The value must therefore be captured from the evaluation strategy while the plan is being built.
	 */
	@Test
	void forcingAStrategyNeverOfferedAtGroupByDispatchIsReportedRatherThanIgnored() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, GROUP_BY_QUERY,
					LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD);
			assertThatThrownBy(() -> QueryResults.asList(preparedQuery.evaluate()))
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("'" + LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD + "'")
					.hasMessageContaining("GROUP BY dispatch");
		}
	}

	/**
	 * The counterpart, and the strongest statement this feature can make: for a {@code GROUP BY} query, forcing
	 * <em>every</em> name in the registry must land in exactly one of two buckets — the strategy runs and returns
	 * precisely what adaptive selection returns, or it fails with the specific "could not be forced" error. Silently
	 * ignoring the request (the bug this test was written for) is in neither bucket, and neither is returning different
	 * results. Sweeping the whole registry avoids hard-coding a guess about which aggregate tag happens to be a
	 * candidate for this shape — exactly the sort of guess that plan changes invalidate.
	 */
	@Test
	void everyForceableStrategyEitherRunsCorrectlyOrExplainsItselfOnAGroupByQuery() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> expected = QueryResults.asList(prepare(conn, GROUP_BY_QUERY, null).evaluate());
			assertThat(expected).isNotEmpty();

			List<String> honored = new ArrayList<>();
			List<String> wrongResults = new ArrayList<>();
			for (String candidate : LmdbNativeForceableStrategies.names()) {
				List<BindingSet> actual;
				try {
					actual = QueryResults.asList(prepare(conn, GROUP_BY_QUERY, candidate).evaluate());
				} catch (QueryEvaluationException e) {
					assertThat(e).as("rejection of forced '%s'", candidate)
							.hasMessageContaining("could not be forced")
							.hasMessageContaining("'" + candidate + "'");
					continue;
				}
				honored.add(candidate);
				if (actual.size() != expected.size() || !actual.containsAll(expected)) {
					wrongResults.add(candidate + " -> " + actual);
				}
			}

			assertThat(wrongResults).as("forced strategies disagreeing with adaptive selection").isEmpty();
			assertThat(honored).as("strategies actually honored for this GROUP BY query").isNotEmpty();
		}
	}

	@Test
	void forcingWcojSucceedsOnAQueryShapedForIt() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailTupleQuery preparedQuery = prepare(conn, MULTI_PATTERN_JOIN_QUERY, LmdbNativeAttemptMetrics.PATH_WCOJ);
			List<BindingSet> result = QueryResults.asList(preparedQuery.evaluate());
			assertThat(result).hasSize(1);
		}
	}
}
